ORDER = list(SRC)
def merge(rows, key):
    out = {}
    for r in rows:
        k = key(r)
        if k in out:
            out[k]['src'] = sorted(set(out[k]['src']) | set(r[4]), key=ORDER.index)
        else:
            assert r[2] != 'x', r
            out[k] = {'fa': r[0], 'tr': r[1], 'he': r[2], 'cat': r[3], 'src': sorted(set(r[4]), key=ORDER.index)}
    return list(out.values())
words = merge(W, lambda r: (r[0], r[1], r[3]))
verbs = merge(V, lambda r: r[0])
for x in verbs:
    parts = x['fa'].split(); x['stem'] = ' '.join(parts[:-1] + [parts[-1][:-1]])
for x in words + verbs:
    x['inList'] = any(s.startswith('L') for s in x['src'])
for x in words: x['id'] = 'w:' + x['fa'] + '|' + x['tr'] + ('|cl' if x['cat'].startswith('נומרטיב') else '')
for x in verbs: x['id'] = 'v:' + x['fa']
ids = [x['id'] for x in words + verbs]; assert len(ids) == len(set(ids)), 'duplicate ids'
data = {'sources': SRC, 'words': words, 'verbs': verbs}
out = sys.argv[1]
if len(sys.argv) > 2:
    open(sys.argv[2], 'w', encoding='utf8').write('// Generated from the course files. Do not edit by hand.\nwindow.VOCAB = ' + json.dumps(data, ensure_ascii=False) + ';\n')
json.dump(data, open(os.path.join(out, 'vocab.json'), 'w', encoding='utf8'), ensure_ascii=False)
with open(os.path.join(out, 'persian_vocab.csv'), 'w', encoding='utf-8-sig', newline='') as f:
    c = csv.writer(f); c.writerow(['סוג','קטגוריה','פרסית','תעתיק','עברית','גזע עבר','ברשימת המילים?','מקורות'])
    for x in words: c.writerow(['מילה', x['cat'], x['fa'], x['tr'], x['he'], '', 'כן' if x['inList'] else 'לא', ' | '.join(SRC[s] for s in x['src'])])
    for x in verbs: c.writerow(['פועל', x['cat'], x['fa'], x['tr'], x['he'], x['stem'], 'כן' if x['inList'] else 'לא', ' | '.join(SRC[s] for s in x['src'])])
print(len(words), 'words', sum(x['inList'] for x in words), 'in lists;', len(verbs), 'verbs', sum(x['inList'] for x in verbs), 'in lists')
